/* Track A · 9.2.1 · RU / EN / ZH */
(function(){"use strict";window.DCH_LIME_921={content:{"ru":{"title":"Выбор окрестности и интерпретация результатов","lead":"Научитесь настраивать локальную область LIME, понимать влияние kernel_width и num_samples и правильно читать веса, коэффициенты и локальную оценку подгонки.","outcomes":["Объяснять, как формируется локальная окрестность и почему она зависит от представления признаков и метрики.","Сравнивать узкую, умеренную и широкую настройку kernel_width.","Различать влияние kernel_width и num_samples на локальное объяснение.","Объяснять преобразование расстояния в вес близости.","Интерпретировать веса строк и коэффициенты локальной модели без причинных выводов.","Сопоставлять f(x₀), g(x₀), local_pred и score.","Проводить контролируемое сравнение настроек LIME на одном объекте."],"sections":[["why","1. Зачем настраивать окрестность",["В уроке 9.1.3 мы проследили общий алгоритм LIME: вокруг выбранного объекта x₀ создаются возмущённые варианты zᵢ, исходная модель f выдаёт для них прогнозы, а локальная модель g обучается с учётом весов близости. Теперь сосредоточимся на решении, которое определяет, какие варианты будут влиять на объяснение и насколько сильно.","Окрестность — не обязательно набор геометрически ближайших строк исходной таблицы. Это выборка возмущённых объектов, для которых рассчитываются расстояния в представлении, используемом explainer, а затем веса. В стандартном табличном LIME расстояния вычисляются в масштабированном пространстве признаков; при дискретизации непрерывных признаков меняется и представление, в котором оценивается близость.","Окрестность задаёт локальный контекст объяснения. Если в неё попали слишком разные варианты, локальная модель может усреднить несколько режимов поведения f. Если эффективная область слишком мала, у g может оказаться мало разнообразной информации для аппроксимации. Поэтому ширину области нужно выбирать осознанно, а не считать параметр технической мелочью."],"neighborhood"],["case","2. Один объект и его возмущённые варианты",["Рассмотрим условный учебный пример. Банк использует классификатор f, который оценивает, относится ли заявка клиента к классу 1 «низкий риск просрочки». Исходный объект x₀: стаж обслуживания — 6 лет, годовой доход — 85 000 условных денежных единиц, долговая нагрузка — 0,28, срок договора — 12 месяцев.","Обозначим синтетические варианты как z₁, z₂ и далее. В таблице показаны несколько возможных изменений признаков. Это иллюстрация принципа, а не реальные записи и не точная трассировка внутреннего sampler библиотеки. В реальном LimeTabularExplainer генерация зависит от статистик обучающих данных, типа признаков, дискретизации и параметров explainer.","Для каждого zᵢ важно различать исходные значения, которые получает f, и расстояние d(x₀,zᵢ), которое вычисляется в представлении, используемом для локального взвешивания. Разница в одной исходной единице не обязательно означает одинаковую близость: признаки могут иметь разные масштабы."],"perturbations"],["width","3. Как kernel_width меняет эффективную окрестность",["Параметр kernel_width задаёт масштаб убывания весов с расстоянием. В стандартной реализации табличного LIME используется экспоненциальное ядро: wᵢ = √exp(−dᵢ² / h²), где dᵢ — расстояние, а h — kernel_width. Это не жёсткая граница: точки за условным радиусом не отбрасываются автоматически, а получают меньший вес.","При малом h вес быстро уменьшается с расстоянием. Локальная модель сильнее ориентируется на очень близкие варианты. Это может лучше сосредоточить объяснение около x₀, но также уменьшает эффективный вклад остальных строк. При большом h веса убывают медленнее, поэтому в обучение заметнее включаются более удалённые варианты. Объяснение охватывает более широкую область, но может хуже отражать тонкое локальное поведение.","Вычислим веса для двух одинаковых расстояний d = 0,5 и d = 1,0 при трёх условных значениях h. При d = 0,5 веса составляют примерно 0,360; 0,801; 0,946 для h = 0,35; 0,75; 1,5 соответственно. При d = 1,0 — примерно 0,017; 0,411; 0,801. Значения рассчитаны по указанной формуле и показывают только влияние масштаба ядра.","В библиотеке значение по умолчанию для табличного explainer рассчитывается как 0,75 × √p, где p — число признаков. Это стартовая настройка реализации, а не доказательство оптимальности. Сравнивайте несколько осмысленных значений на одном объекте, сохраняя остальные настройки и проверяя локальную подгонку.","Эти значения h нужны только для числовой иллюстрации и не переносятся напрямую на практический набор с 30 признаками: подходящий масштаб зависит от распределения расстояний в конкретном представлении."],"widths"],["distance","4. От расстояния к весу",["Расстояние dᵢ отвечает на вопрос, насколько возмущённый вариант отличается от x₀ в выбранном представлении и метрике. Ядро πₓ₀ преобразует это расстояние в вес wᵢ. При стандартном экспоненциальном ядре вес лежит между 0 и 1: исходный объект имеет нулевое расстояние и максимальный вес, а удалённые варианты получают меньший вес.","Например, при h = 0,75 расстояниям 0; 0,2; 0,5 и 1,0 соответствуют веса 1,000; 0,965; 0,801 и 0,411. Это вычисленный учебный пример. Вес не является вероятностью класса, уверенностью модели, оценкой реалистичности записи или важностью отдельного признака. Он задаёт вклад всей строки в локальную подгонку.","Одинаковое расстояние может иметь разный смысл при другой метрике или другом представлении признаков. Поэтому интерпретируя веса, всегда фиксируйте, каким способом explainer измеряет расстояние и какое значение kernel_width использовано."],"distanceWeights"],["samples","5. Сколько возмущённых объектов нужно",["Параметр num_samples задаёт размер генерируемой выборки окрестности, на которой LIME обучает локальное объяснение. Он отвечает за количество синтетических вариантов, а не за то, насколько быстро уменьшаются их веса. За скорость убывания отвечает kernel_width.","При малом num_samples локальная модель строится по меньшему числу возмущённых вариантов. Это быстрее, но выборка может слабее покрывать выбранную область. При большем num_samples появляется больше точек для локальной подгонки, однако растут вычислительные затраты и число запросов к f. Дополнительные точки не исправляют неподходящую ширину ядра или неудачную схему генерации.","Практически сравнивайте несколько размеров выборки при фиксированных объекте, модели, kernel_width и random_state. Смотрите на локальный score, локальное предсказание и состав объяснения. Не делайте вывод «чем больше, тем лучше» по одному числу: важны задача, стоимость вызова f и то, насколько выборка описывает интересующую область.","В стандартном табличном sampler первая строка выборки соответствует самому x₀, поэтому num_samples — общий размер локальной выборки, а не число дополнительных вариантов сверх исходного объекта."],"sampleSizes"],["fit","6. Как веса участвуют в обучении локальной модели",["После генерации вариантов LIME получает ответы исходной модели f(zᵢ), рассчитывает веса wᵢ и обучает простую модель g на интерпретируемом представлении z′ᵢ. Веса задают относительный вклад строк в локальную функцию потерь. Упрощённо задачу можно записать как g* = argmin_g Σᵢ wᵢ · L(f(zᵢ), g(z′ᵢ)) + Ω(g), где Ω(g) ограничивает сложность объяснения.","В таблице показаны условные строки одной локальной выборки. У варианта z₁ вес выше, поэтому при прочих равных он сильнее влияет на обучение g, чем z₄. Но высокий вес не гарантирует, что вариант реалистичен, и не говорит, что его отдельный признак важен.","Локальная модель приближает ответы f в выбранной взвешенной области. Она не переобучает исходный классификатор и не заменяет его. Изменение kernel_width меняет веса; изменение num_samples меняет набор строк; оба параметра могут повлиять на итоговое объяснение разными путями."],"weightedFit"],["coefficients","7. Как читать локальные коэффициенты",["Продолжим условный пример банка и объясним класс 1 «низкий риск просрочки». Предположим, локальная линейная модель g выбрала три условия: стаж больше пяти лет, высокая долговая нагрузка и годовой договор. Коэффициенты ниже — условные учебные значения, а не результат реального запуска LIME.","Коэффициент +0,18 у условия «стаж > 5 лет» означает, что активное условие связано с увеличением оценки локальной модели для класса 1 при прочих фиксированных компонентах этой линейной аппроксимации. Коэффициент −0,11 у условия «высокая долговая нагрузка» указывает на направление уменьшения оценки класса 1. Коэффициент +0,07 у годового договора указывает на положительное направление в той же локальной модели.","Это не изменение вероятности на 18, 11 или 7 процентных пунктов. Коэффициенты относятся к выбранному классу, кодированию признаков, конкретному объекту и конкретной локальной подгонке. Они не являются причинными эффектами и не должны переноситься на всех клиентов или на глобальное поведение f."],"coefficients"],["compare","8. Сопоставление f(x₀), g(x₀) и локального score",["Для одного объекта x₀ сравнивайте три разных результата. f(x₀) — прогноз исходной модели. g(x₀), который в API LIME доступен через local_pred, — прогноз локального суррогата на исходном объекте. score — оценка качества подгонки локальной модели на сгенерированной взвешенной окрестности; для стандартного табличного сценария это локальный R².","В условном примере f(x₀) = 0,78, g(x₀) = 0,74, а локальный score = 0,86. Разница между 0,78 и 0,74 показывает, что локальная модель приближает исходную, но не совпадает с ней точно. Score 0,86 характеризует подгонку g на данной взвешенной выборке, а не точность, калибровку или надёжность исходной модели.","Высокий локальный score не означает, что исходная модель хороша, что объяснение причинно верно или что те же коэффициенты применимы в другой области. Низкий score означает, что выбранная простая модель плохо описывает f в текущей конфигурации окрестности; это повод пересмотреть постановку и параметры, а не скрывать показатель."],"fitComparison"],["workflow","9. Практический порядок выбора настроек",["Начните с одного зафиксированного объекта x₀ и сохраните прогноз исходной модели. Затем задайте базовые параметры explainer и зафиксируйте random_state. Для анализа ширины меняйте только kernel_width; для анализа количества строк меняйте только num_samples.","После каждого запуска записывайте f(x₀), g(x₀), score и несколько условий из as_list. Сравнивайте не только отдельные коэффициенты, но и то, насколько локальная модель согласуется с f в выбранной области. Не объявляйте одну конфигурацию универсально лучшей: выбор зависит от цели объяснения и масштаба локального анализа.","В следующем уроке 9.2.2 мы отдельно разберём устойчивость и ограничения LIME. Здесь достаточно помнить: одна настройка и один запуск дают объяснение для конкретной конфигурации, а не универсальное описание модели."],"workflow"]],"diagrams":{"neighborhood":{"title":"Что входит в локальный контекст","description":"Один исходный объект и условные возмущённые варианты с расстоянием до него","caption":"Условная иллюстрация. Расстояния показаны в пространстве, используемом explainer; это не исходные единицы признаков.","columns":["Объект","Роль","Расстояние до x₀","Контекст"],"rows":[["x₀","Исходный объект","0,00","Центр объяснения"],["z₁","Близкий вариант","0,20","Высокая близость"],["z₂","Умеренно близкий","0,50","Средняя близость"],["z₃","Более удалённый","1,00","Меньшая близость"],["z₄","Удалённый вариант","1,40","Слабый вклад"]]},"perturbations":{"title":"Один клиент и варианты zᵢ","description":"Условные исходные значения признаков для x₀ и четырёх синтетических вариантов","caption":"Все строки и значения условные. Они показывают идею возмущения, а не точный вывод внутреннего sampler LIME.","columns":["Объект","Стаж, лет","Доход в год","Долговая нагрузка","Договор, мес."],"rows":[["x₀","6","85 000","0,28","12"],["z₁","5,5","82 000","0,30","12"],["z₂","6","72 000","0,34","12"],["z₃","7","90 000","0,18","24"],["z₄","3","60 000","0,52","6"]]},"widths":{"title":"Как ширина ядра меняет веса","description":"Вес двух расстояний при трёх значениях kernel_width","caption":"Расчёт по w = √exp(−d² / h²). Условный пример в безразмерной шкале расстояния.","columns":["Расстояние d","h = 0,35 — узкая","h = 0,75 — средняя","h = 1,5 — широкая"],"rows":[["0,5","0,360","0,801","0,946"],["1,0","0,017","0,411","0,801"]]},"distanceWeights":{"title":"Расстояние определяет вес строки","description":"Пример преобразования расстояния в вес при kernel_width 0,75","caption":"Условные вычисленные значения по стандартному экспоненциальному ядру; вес — вклад строки в локальное обучение.","columns":["Расстояние dᵢ","Вес wᵢ","Интерпретация"],"rows":[["0,00","1,000","Исходный объект"],["0,20","0,965","Очень близкий вариант"],["0,50","0,801","Умеренное влияние"],["1,00","0,411","Меньший вклад"]]},"sampleSizes":{"title":"Размер выборки возмущений","description":"Сравнение количества синтетических строк и вычислительных затрат","caption":"Схема выбора параметра, не результат измерения качества. Большее число строк не гарантирует лучшего объяснения.","columns":["num_samples","Объём выборки","Ожидаемый компромисс"],"rows":[["500","Меньше строк","Быстрее; покрытие может быть ограниченным"],["1 500","Средний объём","Больше вариантов для локальной подгонки"],["3 000","Больше строк","Дороже; качество всё ещё зависит от окрестности"]]},"weightedFit":{"title":"Что получает локальная модель g","description":"Согласованные строки, прогнозы исходной модели и веса","caption":"Условные учебные значения. Вес влияет на вклад строки; это не признак клиента и не вероятность класса.","columns":["Строка","Ответ f(zᵢ), класс 1","Вес wᵢ","Вклад в локальную подгонку"],"rows":[["z₁","0,74","0,96","Высокий"],["z₂","0,68","0,80","Заметный"],["z₃","0,83","0,41","Меньший"],["z₄","0,55","0,17","Небольшой"]]},"coefficients":{"title":"Коэффициенты условной локальной модели","description":"Направление коэффициентов для объясняемого класса 1 — низкий риск просрочки","caption":"Условные учебные коэффициенты. Знак показывает направление локальной оценки, а не причинность или процентные пункты вероятности.","columns":["Условие","Коэффициент","Направление для класса 1"],"rows":[["Стаж > 5 лет","+0,18","Положительное"],["Высокая долговая нагрузка","−0,11","Отрицательное"],["Годовой договор","+0,07","Положительное"]]},"fitComparison":{"title":"Три разных показателя","description":"Исходный прогноз, локальный прогноз и качество локальной подгонки","caption":"Все числа условные. Локальный score не является accuracy исходной модели.","columns":["Величина","Значение","Что означает"],"rows":[["f(x₀)","0,78","Прогноз исходной модели"],["g(x₀)","0,74","Прогноз локального суррогата"],["score","0,86","Взвешенный локальный R²"]]},"workflow":{"title":"Порядок настройки и чтения LIME","description":"Девять последовательных действий от фиксации объекта до интерпретации","caption":"Читайте нумерованные шаги сверху вниз. Каждая настройка меняется отдельно, чтобы понять её собственное влияние.","columns":["Шаг","Действие","Что фиксировать или сравнивать"],"rows":[["1","Выбрать x₀","Один и тот же объект"],["2","Записать f(x₀)","Исходный прогноз и класс"],["3","Задать базовую конфигурацию","Метрика, представление, seed"],["4","Изменить kernel_width","Остальные параметры фиксированы"],["5","Изменить num_samples","Остальные параметры фиксированы"],["6","Получить объяснение","as_list и коэффициенты"],["7","Сравнить g(x₀)","local_pred"],["8","Оценить локальную подгонку","score"],["9","Ограничить вывод","Только выбранная область и конфигурация"]]}},"practice":{"title":"Сравнение настроек LIME на одном объекте","intro":"Обучите RandomForestClassifier на наборе Breast Cancer Wisconsin из scikit-learn и объясните один и тот же тестовый объект при разных kernel_width и num_samples. Банковский пример в теории вымышленный; практическая работа использует отдельный реальный учебный набор данных.","task":"Установите зависимости и запустите скрипт. Сначала сравните три значения kernel_width при фиксированном num_samples = 3000. Затем сравните три значения num_samples при фиксированном kernel_width. Объект x₀, исходная модель и random_state остаются неизменными.","steps":["Проверьте исходные вероятности и индекс объясняемого класса.","Сравните kernel_width = 2, значение по умолчанию и 7,0.","Сравните num_samples = 500, 1500 и 3000 при фиксированной ширине.","Для каждого запуска запишите g(x₀), score и условия из as_list.","Объясните различия, не объявляя одно значение универсально лучшим."],"expected":"Скрипт выводит исходные вероятности, g(x₀), локальный score и список условий для каждой конфигурации. Числовые результаты вычисляются при запуске и намеренно не подменяются заранее придуманными значениями.","install":"python -m pip install \"lime==0.2.0.1\" scikit-learn numpy","run":"python lessons/practice/a-9-2-1-lime-neighborhood.py"},"sources":[["Ribeiro, Singh и Guestrin (2016), “Why Should I Trust You? Explaining the Predictions of Any Classifier”, KDD 2016","https://doi.org/10.1145/2939672.2939778"],["Официальный исходный код LIME: LimeTabularExplainer и kernel_width","https://github.com/marcotcr/lime/blob/master/lime/lime_tabular.py"],["Официальный репозиторий LIME и руководство по табличным данным","https://github.com/marcotcr/lime"],["PyPI: пакет lime, версия 0.2.0.1","https://pypi.org/project/lime/0.2.0.1/"],["scikit-learn: Breast Cancer Wisconsin dataset","https://scikit-learn.org/stable/modules/generated/sklearn.datasets.load_breast_cancer.html"],["scikit-learn: RandomForestClassifier","https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.RandomForestClassifier.html"],["Исходный код LIME: взвешенное обучение локальной модели","https://github.com/marcotcr/lime/blob/master/lime/lime_base.py"]],"glossary":[["Локальная окрестность","Набор возмущённых объектов вокруг x₀, используемый для локальной подгонки."],["kernel_width","Параметр масштаба ядра, определяющий скорость убывания весов с расстоянием."],["num_samples","Количество строк в сгенерированной выборке, используемой для локального обучения."],["Ядро (kernel)","Функция, преобразующая расстояние до x₀ в вес близости."],["Вес близости","Коэффициент, задающий вклад строки в локальную функцию потерь."],["Возмущённый объект","Синтетический вариант исходного объекта, используемый для запроса исходной модели."],["Локальная модель g","Простая модель, приближающая ответы f в выбранной окрестности."],["Локальный коэффициент","Коэффициент модели g, интерпретируемый в рамках выбранного объекта, класса и представления."],["local_pred","Результат локальной модели для объясняемого объекта x₀."],["Локальный score","Оценка подгонки локального суррогата на выбранной взвешенной выборке."]],"quiz":[["Что именно регулирует kernel_width?",["Число синтетических строк","Масштаб убывания веса с расстоянием","Число классов модели","Порог классификации"],1,"kernel_width определяет, насколько быстро вес уменьшается при росте расстояния."],["Что произойдёт при увеличении kernel_width при прочих равных?",["Вес удалённых вариантов обычно станет выше","Все удалённые варианты будут удалены","Изменится исходная модель f","Увеличится число признаков"],0,"Более широкое ядро замедляет убывание весов и расширяет эффективную область влияния."],["Как num_samples отличается от kernel_width?",["Оба параметра задают одну и ту же величину","num_samples задаёт размер выборки, kernel_width — масштаб весов","num_samples меняет метрику расстояния","kernel_width задаёт число классов"],1,"Это разные параметры: количество синтетических строк и скорость убывания весов."],["Что означает вес wᵢ?",["Вероятность класса 1","Причинный эффект признака","Относительный вклад строки в локальную подгонку","Уверенность в реальности записи"],2,"Вес регулирует вклад всей строки в обучение локальной модели."],["Что означает коэффициент +0,18 в условном примере?",["Рост вероятности ровно на 18 процентных пунктов","Положительное направление в локальной модели для выбранного класса","Причинное влияние стажа на риск","Глобальную важность стажа"],1,"Коэффициент относится к локальной аппроксимации, а не к причинности или процентным пунктам."],["Что показывает exp.local_pred?",["Предсказание исходной модели на тестовой выборке","Предсказание локального суррогата для x₀","Среднюю точность модели","Число сгенерированных объектов"],1,"local_pred содержит прогноз локальной модели для объясняемого объекта."],["Как правильно трактовать exp.score в этом уроке?",["Как accuracy исходной модели","Как вероятность правильности объяснения","Как локальную оценку подгонки суррогата на взвешенной выборке","Как число признаков"],2,"Локальный score характеризует соответствие g и f в выбранной взвешенной окрестности."],["Какой вывод корректен после одного запуска LIME?",["Те же коэффициенты действуют для всех объектов","Объяснение относится к конкретному объекту и конфигурации","LIME доказал причинность признаков","Высокий score доказывает высокое качество исходной модели"],1,"Локальное объяснение нельзя автоматически обобщать на другие объекты и области."]]},"en":{"title":"Choosing the Neighbourhood and Interpreting Results","lead":"Learn to configure LIME's local region, understand the effects of kernel_width and num_samples, and interpret weights, coefficients, and the local fit score.","outcomes":["Explain how the local neighbourhood is formed and why it depends on feature representation and distance metric.","Compare narrow, medium, and wide kernel_width settings.","Distinguish the effects of kernel_width and num_samples on a local explanation.","Explain how distance is mapped to a proximity weight.","Interpret row weights and local-model coefficients without causal claims.","Compare f(x₀), g(x₀), local_pred, and score.","Run a controlled comparison of LIME settings on one fixed instance."],"sections":[["why","1. Why the neighbourhood needs tuning",["In lesson 9.1.3, we followed the LIME workflow: perturbations zᵢ are generated around an instance x₀, the original model f predicts on them, and a local model g is fitted using proximity weights. This lesson focuses on the decision that controls which variants influence the explanation and how strongly they contribute.","A neighbourhood is not necessarily just the set of nearest rows in the raw table. It is a generated sample of perturbed instances whose distances are computed in the representation used by the explainer and then converted into weights. In standard tabular LIME, distances are computed in a scaled feature space; discretizing continuous features also changes the representation in which proximity is evaluated.","The neighbourhood defines the local context of an explanation. If it includes very different variants, the local model may average several behavioural regimes of f. If its effective region is too narrow, g may receive too little varied information to approximate f. The neighbourhood must therefore be configured deliberately."],"neighborhood"],["case","2. One instance and its perturbed variants",["Consider a hypothetical teaching example. A bank uses a classifier f to estimate whether an application belongs to class 1, “low risk of late payment”. The original instance x₀ has six years of customer tenure, annual income of 85,000 illustrative currency units, a debt-to-income ratio of 0.28, and a 12-month contract.","Let synthetic variants be z₁, z₂, and so on. The table shows possible feature changes. It illustrates the idea; it is not real customer data or an exact trace of the library's internal sampler. In LimeTabularExplainer, generation depends on training-data statistics, feature types, discretization, and explainer settings.","For each zᵢ, distinguish the original values passed to f from the distance d(x₀,zᵢ), which is calculated in the representation used for local weighting. A difference of one raw unit does not necessarily imply the same proximity across features with different scales."],"perturbations"],["width","3. How kernel_width changes the effective neighbourhood",["The kernel_width parameter sets the scale at which weights decay with distance. The standard tabular LIME implementation uses an exponential kernel: wᵢ = √exp(−dᵢ² / h²), where dᵢ is the distance and h is kernel_width. This is not a hard boundary: points outside a notional radius are not automatically discarded; they simply receive smaller weights.","With a small h, weights decrease rapidly as distance grows. The local model is driven more strongly by very close variants. This can focus the explanation around x₀, but it also reduces the effective contribution of other rows. With a large h, weights decay more slowly, so more distant variants contribute more noticeably. The explanation covers a broader region but may reflect fine local behaviour less closely.","For the same distances d = 0.5 and d = 1.0, the weights for three illustrative h values are approximately 0.360, 0.801, 0.946 at h = 0.35, 0.75, 1.5; and 0.017, 0.411, 0.801 at d = 1.0. These values are calculated from the stated formula and isolate the effect of kernel scale.","In the library, the default tabular explainer value is calculated as 0.75 × √p, where p is the number of features. This is an implementation default, not proof of optimality. Compare several meaningful values on the same instance, keep other settings fixed, and inspect local fit.","These h values are only for the numerical illustration and should not be transferred directly to the 30-feature lab dataset: a suitable scale depends on the distance distribution in the chosen representation."],"widths"],["distance","4. From distance to weight",["Distance dᵢ describes how different a perturbed instance is from x₀ in the selected representation and metric. The kernel πₓ₀ maps that distance to a weight wᵢ. With the standard exponential kernel, the weight lies between 0 and 1: the original instance has zero distance and maximum weight, while more distant variants receive less weight.","For h = 0.75, distances 0, 0.2, 0.5, and 1.0 correspond to weights 1.000, 0.965, 0.801, and 0.411. This is a calculated teaching example. A weight is not a class probability, model confidence, measure of record realism, or direct feature importance. It controls the contribution of the whole row to local fitting.","The same numerical distance can mean something different under another metric or feature representation. When interpreting weights, state how the explainer measures distance and which kernel_width was used."],"distanceWeights"],["samples","5. How many perturbed instances are needed?",["The num_samples parameter sets the size of the generated neighbourhood sample used to fit the local explanation. It controls the number of synthetic variants, not how quickly their weights decay. The decay scale is controlled by kernel_width.","With a small num_samples, the local model is fitted on fewer perturbed variants. This is faster, but the sample may cover the selected region less thoroughly. A larger num_samples provides more points for local fitting, while increasing computation and the number of calls to f. Additional points do not fix an unsuitable kernel width or a poor sampling scheme.","In practice, compare several sample sizes while keeping the instance, model, kernel_width, and random_state fixed. Inspect the local score, local prediction, and explanation terms. Do not conclude that more is always better from one number: the task, cost of querying f, and coverage of the region all matter.","In the standard tabular sampler, the first row is x₀ itself. Therefore, num_samples is the total neighbourhood size, not the number of additional variants beyond the original instance."],"sampleSizes"],["fit","6. How weights affect local fitting",["After generating variants, LIME obtains the original model outputs f(zᵢ), calculates weights wᵢ, and fits a simple model g on interpretable representations z′ᵢ. The weights determine the relative contribution of rows to the local loss. In simplified form: g* = argmin_g Σᵢ wᵢ · L(f(zᵢ), g(z′ᵢ)) + Ω(g), where Ω(g) controls explanation complexity.","The table shows hypothetical rows from one local sample. Variant z₁ has a higher weight, so, all else equal, it influences g more than z₄. A high weight does not guarantee that a variant is realistic, and it does not mean that one of its features is important.","The local model approximates f within the selected weighted region. It does not retrain or replace the original classifier. Changing kernel_width changes the weights; changing num_samples changes the generated rows. Both can affect the explanation through different mechanisms."],"weightedFit"],["coefficients","7. Reading local coefficients",["Continue the hypothetical bank example and explain class 1, “low risk of late payment”. Suppose the local linear model g selects three conditions: tenure over five years, high debt burden, and an annual contract. The coefficients below are illustrative teaching values, not the output of an actual LIME run.","A coefficient of +0.18 for “tenure > 5 years” means that the active condition is associated with an increase in the local model's estimate for class 1, holding the other components of this linear approximation fixed. A coefficient of −0.11 for “high debt burden” points in the direction of a lower class-1 estimate. A coefficient of +0.07 for an annual contract points in a positive direction in the same local model.","These are not changes of 18, 11, or 7 percentage points in probability. Coefficients belong to the selected class, feature encoding, particular instance, and particular local fit. They are not causal effects and must not be generalized to all customers or to the global behaviour of f."],"coefficients"],["compare","8. Comparing f(x₀), g(x₀), and the local score",["For one instance x₀, compare three different outputs. f(x₀) is the original model's prediction. g(x₀), exposed by LIME through local_pred, is the local surrogate's prediction at the original instance. score measures the local model's fit on the generated weighted neighbourhood; in the standard tabular classification setting, it is a local R² score.","In the hypothetical example, f(x₀) = 0.78, g(x₀) = 0.74, and the local score = 0.86. The difference between 0.78 and 0.74 shows that the local model approximates the original model but does not match it exactly. A score of 0.86 describes g's fit on this weighted sample, not the accuracy, calibration, or reliability of the original model.","A high local score does not prove that the original model is good, that the explanation is causal, or that the same coefficients apply elsewhere. A low score means that the chosen simple model describes f poorly under the current neighbourhood configuration; it is a reason to review the setup and parameters, not to hide the metric."],"fitComparison"],["workflow","9. A practical parameter-selection routine",["Start with one fixed instance x₀ and record the original model prediction. Set baseline explainer parameters and fix random_state. To study neighbourhood width, change only kernel_width; to study sample size, change only num_samples.","After each run, record f(x₀), g(x₀), score, and several conditions from as_list. Compare not only individual coefficients but also how well the local model agrees with f in the selected region. Do not declare one configuration universally best: the choice depends on the explanation goal and the scale of local analysis.","Lesson 9.2.2 will examine LIME's stability and limitations separately. For now, remember that one setting and one run produce an explanation for a particular configuration, not a universal description of the model."],"workflow"]],"diagrams":{"neighborhood":{"title":"What belongs to the local context","description":"One original instance and illustrative perturbed variants with their distances","caption":"Illustrative example. Distances use the explainer's feature space; they are not raw feature units.","columns":["Instance","Role","Distance to x₀","Context"],"rows":[["x₀","Original instance","0.00","Explanation centre"],["z₁","Nearby variant","0.20","High proximity"],["z₂","Moderately near","0.50","Medium proximity"],["z₃","More distant","1.00","Lower proximity"],["z₄","Distant variant","1.40","Small contribution"]]},"perturbations":{"title":"One customer and variants zᵢ","description":"Illustrative original feature values for x₀ and four synthetic variants","caption":"All rows and values are hypothetical. They illustrate perturbation, not the exact output of LIME's internal sampler.","columns":["Instance","Tenure, years","Annual income","Debt ratio","Contract, months"],"rows":[["x₀","6","85,000","0.28","12"],["z₁","5.5","82,000","0.30","12"],["z₂","6","72,000","0.34","12"],["z₃","7","90,000","0.18","24"],["z₄","3","60,000","0.52","6"]]},"widths":{"title":"How kernel width changes weights","description":"Weights for two distances under three kernel_width values","caption":"Calculated using w = √exp(−d² / h²). Illustrative example in dimensionless distance units.","columns":["Distance d","h = 0.35 — narrow","h = 0.75 — medium","h = 1.5 — wide"],"rows":[["0.5","0.360","0.801","0.946"],["1.0","0.017","0.411","0.801"]]},"distanceWeights":{"title":"Distance determines each row's weight","description":"Example mapping from distance to weight at kernel_width 0.75","caption":"Illustrative calculated values using the standard exponential kernel; a weight controls a row's contribution to local fitting.","columns":["Distance dᵢ","Weight wᵢ","Interpretation"],"rows":[["0.00","1.000","Original instance"],["0.20","0.965","Very close variant"],["0.50","0.801","Moderate contribution"],["1.00","0.411","Smaller contribution"]]},"sampleSizes":{"title":"Size of the perturbation sample","description":"Comparison of synthetic row counts and computational trade-offs","caption":"Parameter-selection schematic, not measured quality results. More rows do not guarantee a better explanation.","columns":["num_samples","Sample size","Expected trade-off"],"rows":[["500","Fewer rows","Faster; coverage may be limited"],["1,500","Medium sample","More variants for local fitting"],["3,000","More rows","More costly; quality still depends on the neighbourhood"]]},"weightedFit":{"title":"What the local model g receives","description":"Aligned rows, original-model predictions, and proximity weights","caption":"Hypothetical teaching values. A weight controls row contribution; it is not a customer feature or class probability.","columns":["Row","f(zᵢ), class 1","Weight wᵢ","Contribution to local fit"],"rows":[["z₁","0.74","0.96","High"],["z₂","0.68","0.80","Noticeable"],["z₃","0.83","0.41","Smaller"],["z₄","0.55","0.17","Small"]]},"coefficients":{"title":"Coefficients of an illustrative local model","description":"Coefficient directions for the explained class 1 — low risk of late payment","caption":"Hypothetical teaching coefficients. The sign shows the direction of the local estimate, not causation or probability percentage points.","columns":["Condition","Coefficient","Direction for class 1"],"rows":[["Tenure > 5 years","+0.18","Positive"],["High debt burden","−0.11","Negative"],["Annual contract","+0.07","Positive"]]},"fitComparison":{"title":"Three different quantities","description":"Original prediction, local prediction, and local fit quality","caption":"All values are hypothetical. The local score is not the original model's accuracy.","columns":["Quantity","Value","Meaning"],"rows":[["f(x₀)","0.78","Original model prediction"],["g(x₀)","0.74","Local surrogate prediction"],["score","0.86","Weighted local R²"]]},"workflow":{"title":"A routine for tuning and reading LIME","description":"Nine sequential actions from fixing an instance to interpreting the result","caption":"Read the numbered steps from top to bottom. Change one setting at a time to isolate its effect.","columns":["Step","Action","What to hold fixed or compare"],"rows":[["1","Choose x₀","The same instance"],["2","Record f(x₀)","Original prediction and class"],["3","Set a baseline","Metric, representation, seed"],["4","Change kernel_width","Keep other parameters fixed"],["5","Change num_samples","Keep other parameters fixed"],["6","Get the explanation","as_list and coefficients"],["7","Compare g(x₀)","local_pred"],["8","Assess local fit","score"],["9","Limit the conclusion","Only this region and configuration"]]}},"practice":{"title":"Comparing LIME settings on one instance","intro":"Train a RandomForestClassifier on scikit-learn's Breast Cancer Wisconsin dataset and explain the same test instance under different kernel_width and num_samples settings. The bank example in the theory is hypothetical; the lab uses a separate real teaching dataset.","task":"Install the dependencies and run the script. First compare three kernel_width values with num_samples fixed at 3,000. Then compare three num_samples values with kernel_width fixed. The instance x₀, original model, and random_state remain unchanged.","steps":["Check the original probabilities and the index of the explained class.","Compare kernel_width = 2, the default value, and 7.0.","Compare num_samples = 500, 1,500, and 3,000 at a fixed width.","For each run, record g(x₀), score, and the conditions returned by as_list.","Explain the differences without declaring one value universally best."],"expected":"The script prints original probabilities, g(x₀), the local score, and conditions for each configuration. Numeric results are computed at runtime and are not replaced with invented values.","install":"python -m pip install \"lime==0.2.0.1\" scikit-learn numpy","run":"python lessons/practice/a-9-2-1-lime-neighborhood.py"},"sources":[["Ribeiro, Singh, and Guestrin (2016), “Why Should I Trust You? Explaining the Predictions of Any Classifier”, KDD 2016","https://doi.org/10.1145/2939672.2939778"],["Official LIME source: LimeTabularExplainer and kernel_width","https://github.com/marcotcr/lime/blob/master/lime/lime_tabular.py"],["Official LIME repository and tabular-data tutorial","https://github.com/marcotcr/lime"],["PyPI: lime package, version 0.2.0.1","https://pypi.org/project/lime/0.2.0.1/"],["scikit-learn: Breast Cancer Wisconsin dataset","https://scikit-learn.org/stable/modules/generated/sklearn.datasets.load_breast_cancer.html"],["scikit-learn: RandomForestClassifier","https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.RandomForestClassifier.html"],["LIME source: weighted local-model fitting","https://github.com/marcotcr/lime/blob/master/lime/lime_base.py"]],"glossary":[["Local neighbourhood","A set of perturbed instances around x₀ used for local fitting."],["kernel_width","Kernel scale parameter controlling how quickly weights decay with distance."],["num_samples","Number of rows in the generated sample used for local fitting."],["Kernel","A function that maps distance from x₀ to a proximity weight."],["Proximity weight","A coefficient controlling a row's contribution to the local loss."],["Perturbed instance","A synthetic variant of the original instance used to query the original model."],["Local model g","A simple model approximating f's outputs in the selected neighbourhood."],["Local coefficient","A coefficient of g interpreted for the selected instance, class, and representation."],["local_pred","The local model's output for the explained instance x₀."],["Local score","A fit measure for the local surrogate on the selected weighted sample."]],"quiz":[["What does kernel_width control?",["The number of synthetic rows","The scale of weight decay with distance","The number of model classes","The classification threshold"],1,"kernel_width controls how quickly a weight decreases as distance grows."],["What usually happens when kernel_width increases, all else equal?",["Distant variants receive higher weights","All distant variants are removed","The original model f changes","The number of features increases"],0,"A wider kernel slows weight decay and broadens the effective region of influence."],["How does num_samples differ from kernel_width?",["They set the same quantity","num_samples sets sample size; kernel_width sets the weight scale","num_samples changes the distance metric","kernel_width sets the number of classes"],1,"They are different parameters: number of synthetic rows and rate of weight decay."],["What does a weight wᵢ mean?",["Probability of class 1","A causal feature effect","A row's relative contribution to local fitting","Confidence that the record is realistic"],2,"The weight controls the contribution of the whole row to local model fitting."],["What does +0.18 mean in the hypothetical example?",["An exact increase of 18 percentage points","A positive direction in the local model for the selected class","A causal effect of tenure on risk","Global importance of tenure"],1,"The coefficient belongs to a local approximation, not causality or percentage points."],["What does exp.local_pred provide?",["The original model's test-set prediction","The local surrogate prediction for x₀","The model's average accuracy","The number of generated instances"],1,"local_pred contains the local model's prediction for the explained instance."],["How should exp.score be interpreted here?",["As the original model's accuracy","As the probability that the explanation is correct","As the surrogate's local fit score on the weighted sample","As the number of features"],2,"The local score measures agreement between g and f in the selected weighted neighbourhood."],["Which conclusion is valid after one LIME run?",["The same coefficients apply to every instance","The explanation applies to a particular instance and configuration","LIME proves feature causality","A high score proves the original model is high quality"],1,"A local explanation cannot automatically be generalized to other instances or regions."]]},"zh":{"title":"邻域选择与结果解读","lead":"学习配置 LIME 的局部区域，理解 kernel_width 与 num_samples 的影响，并正确解读权重、系数和局部拟合分数。","outcomes":["解释局部邻域如何形成，以及它为何取决于特征表示和距离度量。","比较较窄、中等和较宽的 kernel_width 设置。","区分 kernel_width 与 num_samples 对局部解释的影响。","解释距离如何映射为邻近权重。","解读样本行权重和局部模型系数，但不作因果推断。","比较 f(x₀)、g(x₀)、local_pred 和 score。","在同一个固定样本上控制变量并比较 LIME 设置。"],"sections":[["why","1. 为什么需要调整邻域",["在 9.1.3 课中，我们梳理了 LIME 的流程：围绕样本 x₀ 生成扰动变体 zᵢ，由原模型 f 对其预测，再使用邻近权重拟合局部模型 g。本课聚焦一个关键决策：哪些变体会影响解释，以及它们的影响有多大。","邻域不一定只是原始表格中几何距离最近的若干行。它是由扰动样本构成的集合，解释器会在其使用的特征表示中计算距离，再将距离转换为权重。在标准表格 LIME 中，距离是在缩放后的特征空间计算的；连续特征的离散化也会改变评估邻近程度时所使用的表示。","邻域定义了解释的局部上下文。如果其中包含差异很大的变体，局部模型可能会平均 f 的多种行为模式。如果有效区域过窄，g 获得的变化信息可能不足以近似 f。因此，必须有意识地配置邻域。"],"neighborhood"],["case","2. 一个样本及其扰动变体",["考虑一个虚构的教学案例。银行使用分类器 f 判断申请是否属于类别 1“逾期风险较低”。原始样本 x₀ 的客户服务年限为 6 年，年收入为 85,000 个示意货币单位，债务收入比为 0.28，合同期限为 12 个月。","将合成变体记为 z₁、z₂ 等。表格展示了可能发生的特征变化。这只是原理示意，并非真实客户记录，也不是库内部采样器的精确轨迹。LimeTabularExplainer 的实际生成取决于训练数据统计、特征类型、离散化方式和解释器设置。","对于每个 zᵢ，要区分传给 f 的原始特征值，以及在局部加权表示中计算的距离 d(x₀,zᵢ)。不同量纲的特征即使在原始数值上相差一个单位，也不一定具有相同的邻近程度。"],"perturbations"],["width","3. kernel_width 如何改变有效邻域",["kernel_width 参数控制权重随距离衰减的尺度。标准表格 LIME 实现使用指数核：wᵢ = √exp(−dᵢ² / h²)，其中 dᵢ 是距离，h 是 kernel_width。这不是硬性边界：超出某个假想半径的点不会自动被删除，只是获得较小的权重。","h 较小时，权重会随距离快速下降，局部模型更受非常接近的变体影响。这有助于聚焦 x₀ 附近，但也会降低其他样本的有效贡献。h 较大时，权重下降较慢，较远的变体也会产生更明显的影响。解释覆盖范围更广，但可能较难反映细微的局部行为。","对于相同的距离 d = 0.5 和 d = 1.0，三个示意 h 值对应的权重分别约为：当 d = 0.5 时，h = 0.35、0.75、1.5 对应 0.360、0.801、0.946；当 d = 1.0 时，对应 0.017、0.411、0.801。这些数值由上述公式计算，仅用于展示核尺度的影响。","这些 h 值仅用于数值示意，不能直接套用到包含 30 个特征的实践数据集；合适的尺度取决于所选表示中的距离分布。"],"widths"],["distance","4. 从距离到权重",["距离 dᵢ 表示扰动样本在所选特征表示和度量下与 x₀ 的差异。核函数 πₓ₀ 将距离映射为权重 wᵢ。使用标准指数核时，权重介于 0 和 1 之间：原始样本距离为零，权重最大；距离更远的变体权重更小。","当 h = 0.75 时，距离 0、0.2、0.5 和 1.0 对应的权重分别为 1.000、0.965、0.801 和 0.411。这是经过计算的教学示例。权重不是类别概率、模型置信度、记录真实性评价，也不是单个特征的重要性。它控制整行样本对局部拟合的贡献。","在其他度量或特征表示下，相同的数值距离可能具有不同含义。因此，解释权重时必须说明解释器如何计算距离，以及使用了哪个 kernel_width。"],"distanceWeights"],["samples","5. 需要多少个扰动样本？",["num_samples 参数设置用于拟合局部解释的邻域样本数量。它控制合成变体的数量，而不是权重衰减的速度。权重衰减尺度由 kernel_width 控制。","num_samples 较小时，局部模型使用较少的扰动变体进行拟合，运行更快，但样本可能无法充分覆盖所选区域。num_samples 较大时，局部拟合可使用更多样本，但计算成本和对 f 的调用次数也会增加。增加样本无法修复不合适的核宽度或不合理的采样方案。","实践中，应固定样本、模型、kernel_width 和 random_state，再比较不同样本数量。观察局部 score、局部预测和解释条件。不能仅凭一个数字得出“越多越好”的结论；任务目标、调用 f 的成本以及区域覆盖情况都很重要。","In the standard tabular sampler, the first row is x₀ itself. Therefore, num_samples is the total neighbourhood size, not the number of additional variants beyond the original instance.","在标准表格采样器中，样本的第一行就是 x₀。因此，num_samples 表示邻域样本总数，而不是原始样本之外的额外变体数量。"],"sampleSizes"],["fit","6. 权重如何参与局部拟合",["生成变体后，LIME 获取原模型输出 f(zᵢ)，计算权重 wᵢ，并在可解释表示 z′ᵢ 上拟合简单模型 g。权重决定每一行对局部损失的相对贡献。简化表示为：g* = argmin_g Σᵢ wᵢ · L(f(zᵢ), g(z′ᵢ)) + Ω(g)，其中 Ω(g) 用于限制解释复杂度。","表格展示了同一个局部样本中的示意行。变体 z₁ 的权重较高，因此在其他条件相同的情况下，它对 g 的影响比 z₄ 更大。但高权重并不保证变体真实，也不意味着其中某个特征很重要。","局部模型只近似所选加权区域中的 f。它不会重新训练或替代原分类器。改变 kernel_width 会改变权重；改变 num_samples 会改变生成的样本行。两者通过不同机制影响最终解释。"],"weightedFit"],["coefficients","7. 如何解读局部系数",["继续使用银行的虚构案例，并解释类别 1“逾期风险较低”。假设局部线性模型 g 选出三个条件：服务年限超过五年、债务负担较高、年度合同。下面的系数是虚构的教学数值，并非真实运行 LIME 的结果。","条件“服务年限 > 5 年”的系数 +0.18 表示：在该线性近似中，其他组成部分保持不变时，该条件与类别 1 局部估计值增加相关。“债务负担较高”的系数 −0.11 指向类别 1 估计值降低的方向。年度合同的系数 +0.07 则指向同一局部模型中的正向变化。","这些数值不表示概率变化了 18、11 或 7 个百分点。系数属于指定类别、特征编码、特定样本和特定局部拟合。它们不是因果效应，也不能推广到所有客户或 f 的全局行为。"],"coefficients"],["compare","8. 比较 f(x₀)、g(x₀) 与局部 score",["对于同一个样本 x₀，需要区分三个不同结果。f(x₀) 是原模型的预测。g(x₀) 是局部代理模型在原始样本上的预测，可通过 LIME 的 local_pred 获取。score 衡量局部模型在生成的加权邻域上的拟合程度；在标准表格分类场景中，它是局部 R² 分数。","在虚构示例中，f(x₀) = 0.78，g(x₀) = 0.74，局部 score = 0.86。0.78 与 0.74 的差异说明局部模型是在近似原模型，而不是与其完全相同。0.86 描述的是 g 在该加权样本上的拟合，不是原模型的准确率、校准度或可靠性。","较高的局部 score 并不能证明原模型优秀、解释具有因果意义，或相同系数适用于其他区域。较低的 score 表示在当前邻域配置下，所选简单模型无法很好地描述 f；这提示我们检查问题设定和参数，而不是隐藏指标。"],"fitComparison"],["workflow","9. 参数选择的实践流程",["先固定一个样本 x₀，并记录原模型预测。设置解释器的基准参数并固定 random_state。研究邻域宽度时，只改变 kernel_width；研究样本数量时，只改变 num_samples。","每次运行后记录 f(x₀)、g(x₀)、score，以及 as_list 返回的若干条件。比较的不只是单个系数，还要看局部模型在选定区域内与 f 的一致程度。不要宣称某种配置在所有情况下都最好；选择取决于解释目标和局部分析尺度。","下一课 9.2.2 将专门讨论 LIME 的稳定性与局限。本课只需记住：一次设置和一次运行产生的是特定配置下的解释，而不是对整个模型的普遍描述。"],"workflow"]],"diagrams":{"neighborhood":{"title":"局部上下文包含什么","description":"一个原始样本及其扰动变体，以及它们到中心的距离","caption":"示意示例。距离在解释器使用的特征空间中计算，并非原始特征单位。","columns":["样本","角色","到 x₀ 的距离","上下文"],"rows":[["x₀","原始样本","0.00","解释中心"],["z₁","邻近变体","0.20","邻近程度高"],["z₂","中等距离","0.50","邻近程度中等"],["z₃","较远样本","1.00","邻近程度较低"],["z₄","远距离变体","1.40","贡献较小"]]},"perturbations":{"title":"同一客户及其变体 zᵢ","description":"x₀ 和四个合成变体的示意原始特征值","caption":"所有行和数值均为虚构，仅用于说明扰动，并非 LIME 内部采样器的精确输出。","columns":["样本","服务年限","年收入","债务收入比","合同期限（月）"],"rows":[["x₀","6","85,000","0.28","12"],["z₁","5.5","82,000","0.30","12"],["z₂","6","72,000","0.34","12"],["z₃","7","90,000","0.18","24"],["z₄","3","60,000","0.52","6"]]},"widths":{"title":"核宽度如何改变权重","description":"三个 kernel_width 值下两个距离对应的权重","caption":"根据 w = √exp(−d² / h²) 计算。无量纲距离的示意示例。","columns":["距离 d","h = 0.35 — 窄","h = 0.75 — 中等","h = 1.5 — 宽"],"rows":[["0.5","0.360","0.801","0.946"],["1.0","0.017","0.411","0.801"]]},"distanceWeights":{"title":"距离决定每一行的权重","description":"kernel_width 为 0.75 时距离到权重的映射示例","caption":"使用标准指数核计算的示意值；权重控制样本行对局部拟合的贡献。","columns":["距离 dᵢ","权重 wᵢ","解释"],"rows":[["0.00","1.000","原始样本"],["0.20","0.965","非常接近的变体"],["0.50","0.801","中等贡献"],["1.00","0.411","较小贡献"]]},"sampleSizes":{"title":"扰动样本的规模","description":"合成样本行数量与计算成本的比较","caption":"参数选择示意，并非质量测量结果。更多样本不保证解释更好。","columns":["num_samples","样本规模","预期权衡"],"rows":[["500","较少样本","速度较快；覆盖可能有限"],["1,500","中等规模","为局部拟合提供更多变体"],["3,000","较多样本","成本更高；质量仍取决于邻域"]]},"weightedFit":{"title":"局部模型 g 接收哪些信息","description":"对应的样本行、原模型预测和邻近权重","caption":"虚构教学数值。权重控制样本行的贡献，不是客户特征，也不是类别概率。","columns":["样本行","f(zᵢ)，类别 1","权重 wᵢ","对局部拟合的贡献"],"rows":[["z₁","0.74","0.96","高"],["z₂","0.68","0.80","明显"],["z₃","0.83","0.41","较小"],["z₄","0.55","0.17","较低"]]},"coefficients":{"title":"示意局部模型的系数","description":"被解释类别 1“逾期风险较低”的系数方向","caption":"虚构教学系数。符号表示局部估计方向，不代表因果关系或概率百分点。","columns":["条件","系数","对类别 1 的方向"],"rows":[["服务年限 > 5 年","+0.18","正向"],["债务负担较高","−0.11","负向"],["年度合同","+0.07","正向"]]},"fitComparison":{"title":"三个不同的量","description":"原模型预测、局部预测和局部拟合质量","caption":"所有数值均为虚构。局部 score 不是原模型的准确率。","columns":["量","数值","含义"],"rows":[["f(x₀)","0.78","原模型预测"],["g(x₀)","0.74","局部代理模型预测"],["score","0.86","加权局部 R²"]]},"workflow":{"title":"调整和解读 LIME 的步骤","description":"从固定样本到解释结果的九个连续操作","caption":"按编号从上到下阅读。每次只改变一个设置，以区分其影响。","columns":["步骤","操作","需要固定或比较的内容"],"rows":[["1","选择 x₀","始终使用同一个样本"],["2","记录 f(x₀)","原模型预测及类别"],["3","设置基准配置","度量、表示方式、随机种子"],["4","改变 kernel_width","固定其他参数"],["5","改变 num_samples","固定其他参数"],["6","获取解释","as_list 和系数"],["7","比较 g(x₀)","local_pred"],["8","评估局部拟合","score"],["9","限制结论范围","仅适用于该区域和配置"]]}},"practice":{"title":"在同一个样本上比较 LIME 设置","intro":"使用 scikit-learn 的 Breast Cancer Wisconsin 数据集训练 RandomForestClassifier，并在不同 kernel_width 与 num_samples 设置下解释同一个测试样本。理论中的银行案例是虚构的；实践使用另一份真实教学数据集。","task":"安装依赖并运行脚本。首先固定 num_samples = 3000，比较三个 kernel_width 值。然后固定 kernel_width，比较三个 num_samples 值。整个实验保持样本 x₀、原模型和 random_state 不变。","steps":["检查原始类别概率和待解释类别的索引。","比较 kernel_width = 2、默认值和 7.0。","在固定宽度下比较 num_samples = 500、1500 和 3000。","记录每次运行的 g(x₀)、score 以及 as_list 返回的条件。","解释差异，不要宣称某个数值在所有情况下都最好。"],"expected":"脚本输出原始概率、g(x₀)、局部 score 以及各配置下的条件。数值在运行时计算，不使用虚构的预设结果。","install":"python -m pip install \"lime==0.2.0.1\" scikit-learn numpy","run":"python lessons/practice/a-9-2-1-lime-neighborhood.py"},"sources":[["Ribeiro、Singh 与 Guestrin（2016）：“Why Should I Trust You? Explaining the Predictions of Any Classifier”，KDD 2016","https://doi.org/10.1145/2939672.2939778"],["LIME 官方源码：LimeTabularExplainer 与 kernel_width","https://github.com/marcotcr/lime/blob/master/lime/lime_tabular.py"],["LIME 官方仓库与表格数据教程","https://github.com/marcotcr/lime"],["PyPI：lime 软件包，版本 0.2.0.1","https://pypi.org/project/lime/0.2.0.1/"],["scikit-learn：Breast Cancer Wisconsin 数据集","https://scikit-learn.org/stable/modules/generated/sklearn.datasets.load_breast_cancer.html"],["scikit-learn：RandomForestClassifier","https://scikit-learn.org/stable/modules/generated/sklearn.ensemble.RandomForestClassifier.html"],["LIME 源码：局部模型的加权拟合","https://github.com/marcotcr/lime/blob/master/lime/lime_base.py"]],"glossary":[["局部邻域","围绕 x₀、用于局部拟合的一组扰动样本。"],["kernel_width","控制权重随距离衰减速度的核尺度参数。"],["num_samples","用于局部拟合的生成样本行数量。"],["核函数（kernel）","将样本到 x₀ 的距离映射为邻近权重的函数。"],["邻近权重","控制样本行对局部损失贡献的系数。"],["扰动样本","用于查询原模型的原始样本合成变体。"],["局部模型 g","在所选邻域中近似 f 输出的简单模型。"],["局部系数","在指定样本、类别和表示方式下解释的 g 模型系数。"],["local_pred","局部模型对待解释样本 x₀ 的输出。"],["局部 score","局部代理模型在所选加权样本上的拟合度量。"]],"quiz":[["kernel_width 控制什么？",["合成样本行的数量","权重随距离衰减的尺度","模型类别数量","分类阈值"],1,"kernel_width 控制距离增加时权重下降的速度。"],["其他条件相同时，增大 kernel_width 通常会怎样？",["较远变体获得更高权重","所有远距离变体都会被删除","原模型 f 发生变化","特征数量增加"],0,"更宽的核会减慢权重衰减，并扩大有效影响区域。"],["num_samples 与 kernel_width 有什么区别？",["两个参数控制相同的量","num_samples 设置样本数量，kernel_width 设置权重尺度","num_samples 改变距离度量","kernel_width 设置类别数量"],1,"它们是不同参数：合成样本行数量与权重衰减速度。"],["权重 wᵢ 表示什么？",["类别 1 的概率","特征的因果效应","样本行对局部拟合的相对贡献","记录真实的置信度"],2,"权重控制整行样本对局部模型拟合的贡献。"],["虚构示例中的 +0.18 表示什么？",["概率准确增加 18 个百分点","所选类别局部模型中的正向方向","服务年限对风险的因果影响","服务年限的全局重要性"],1,"该系数属于局部近似，不表示因果关系或概率百分点。"],["exp.local_pred 提供什么？",["原模型在测试集上的预测","局部代理模型对 x₀ 的预测","模型平均准确率","生成样本数量"],1,"local_pred 保存局部模型对待解释样本的预测。"],["在本课中应如何解释 exp.score？",["原模型的准确率","解释正确的概率","局部代理模型在加权样本上的拟合分数","特征数量"],2,"局部 score 衡量 g 与 f 在所选加权邻域中的一致程度。"],["一次 LIME 运行后，哪种结论是正确的？",["相同系数适用于所有样本","解释适用于特定样本和配置","LIME 证明了特征因果关系","高 score 证明原模型质量很高"],1,"局部解释不能自动推广到其他样本或区域。"]]}},practiceCode:"\"\"\"Compare LIME neighbourhood settings on one fixed tabular instance.\n\nInstall:\n    python -m pip install \"lime==0.2.0.1\" scikit-learn numpy\n\nRun:\n    python lessons/practice/a-9-2-1-lime-neighborhood.py\n\nThe bank customer example in the lesson is hypothetical. This lab uses the\nseparate Breast Cancer Wisconsin dataset bundled with scikit-learn.\n\"\"\"\nimport numpy as np\nfrom lime.lime_tabular import LimeTabularExplainer\nfrom sklearn.datasets import load_breast_cancer\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.model_selection import train_test_split\n\nSEED = 42\ndata = load_breast_cancer()\nX_train, X_test, y_train, y_test = train_test_split(\n    data.data,\n    data.target,\n    test_size=0.25,\n    stratify=data.target,\n    random_state=SEED,\n)\nmodel = RandomForestClassifier(\n    n_estimators=240,\n    min_samples_leaf=3,\n    random_state=SEED,\n    n_jobs=-1,\n).fit(X_train, y_train)\n\nclass_names = [str(name) for name in data.target_names]\ninstance_index = 0\nx0 = X_test[instance_index]\nproba = model.predict_proba(x0.reshape(1, -1))[0]\nclass_id = int(np.argmax(proba))\ndefault_width = float(np.sqrt(X_train.shape[1]) * 0.75)\n\ndef build_explainer(kernel_width):\n    \"\"\"Create a fresh explainer so each comparison starts from the same seed.\"\"\"\n    return LimeTabularExplainer(\n        training_data=X_train,\n        feature_names=list(data.feature_names),\n        class_names=class_names,\n        mode=\"classification\",\n        discretize_continuous=True,\n        kernel_width=float(kernel_width),\n        random_state=SEED,\n    )\n\ndef explain(kernel_width, num_samples):\n    explainer = build_explainer(kernel_width)\n    return explainer.explain_instance(\n        data_row=x0,\n        predict_fn=model.predict_proba,\n        labels=(class_id,),\n        num_features=5,\n        num_samples=int(num_samples),\n    )\n\ndef first_scalar(value, label_index):\n    \"\"\"Read a scalar from LIME's selected-label output across API shapes.\"\"\"\n    if isinstance(value, dict):\n        value = value[label_index]\n    values = np.asarray(value).reshape(-1)\n    if values.size == 0:\n        raise ValueError(\"LIME returned an empty local result\")\n    return float(values[0])\n\n\ndef report(label, kernel_width, num_samples):\n    exp = explain(kernel_width, num_samples)\n    local_prediction = first_scalar(exp.local_pred, class_id)\n    local_score = first_scalar(exp.score, class_id)\n    print(f\"\\n{label}\")\n    print(f\"  kernel_width: {kernel_width:.3f}\")\n    print(f\"  num_samples:  {num_samples}\")\n    print(f\"  f(x0), class {class_id}: {proba[class_id]:.4f}\")\n    print(f\"  g(x0):        {local_prediction:.4f}\")\n    print(f\"  local score:  {local_score:.4f}\")\n    print(\"  local conditions:\")\n    for condition, coefficient in exp.as_list(label=class_id):\n        print(f\"    {condition}: {coefficient:+.4f}\")\n    return exp\n\nprint(\"Dataset: Breast Cancer Wisconsin (scikit-learn)\")\nprint(\"Class names:\", class_names)\nprint(\"Explained row:\", instance_index)\nprint(\"Model classes:\", model.classes_.tolist())\nprint(\"Original probabilities:\", np.round(proba, 4).tolist())\nprint(\"Default-width reference:\", round(default_width, 3))\n\nprint(\"\\n=== Compare kernel_width; keep num_samples fixed ===\")\nfor width in (2.0, default_width, 7.0):\n    report(\"Kernel-width comparison\", width, 3000)\n\nprint(\"\\n=== Compare num_samples; keep kernel_width fixed ===\")\nfor sample_count in (500, 1500, 3000):\n    report(\"Sample-count comparison\", default_width, sample_count)\n\nprint(\"\\nInterpretation checklist:\")\nprint(\"- f(x0) is the original classifier probability for the selected class.\")\nprint(\"- g(x0) is the local surrogate prediction at the same instance.\")\nprint(\"- local score is a weighted local fit measure, not test accuracy.\")\nprint(\"- Coefficients describe this local surrogate; they are not causal effects.\")\nprint(\"- Compare configurations; do not assume more samples or a wider kernel is always better.\")\n"};})();
